    recap: [
      '<b>ಗ್ಲೈಕಾಲಿಸಿಸ್</b> (ಗ್ರೀಕ್ <i>glycos</i> = ಸಕ್ಕರೆ, <i>lysis</i> = ವಿಭಜನೆ): ಗ್ಲೂಕೋಸ್ ಭಾಗಶಃ ಆಕ್ಸಿಡೀಕರಣಗೊಂಡು <b>2 ಪೈರುವಿಕ್ ಆಮ್ಲದ ಅಣುಗಳು</b> ಉಂಟಾಗುತ್ತವೆ',
      '<b>ಎಂಬ್ಡೆನ್, ಮೆಯರ್‌ಹಾಫ್ ಮತ್ತು ಪರ್ನಾಸ್</b> ನೀಡಿದ ಯೋಜನೆ &mdash; <b>EMP ಪಥ</b>; ಎಲ್ಲಾ ಜೀವಿಗಳ <b>ಕೋಶದ್ರವ್ಯ</b>ದಲ್ಲಿ ನಡೆಯುತ್ತದೆ',
      'ಅವಾಯುಜೀವಿಗಳಲ್ಲಿ ಇದೇ <b>ಏಕೈಕ</b> ಉಸಿರಾಟ ಕ್ರಿಯೆ; ಇದರಲ್ಲಿ <b>10 ಕ್ರಿಯೆಗಳು</b>, ಪ್ರತಿಯೊಂದೂ ಕಿಣ್ವ ನಿಯಂತ್ರಿತ',
      '<b>ATP ಬಳಕೆ</b> 2 ಹಂತಗಳಲ್ಲಿ (ಗ್ಲೂಕೋಸ್ &rarr; G-6-P, <b>ಹೆಕ್ಸೋಕೈನೇಸ್</b>; F-6-P &rarr; ಫ್ರಕ್ಟೋಸ್ 1,6-ಬೈಸ್ಫಾಸ್ಫೇಟ್); <b>PGAL &rarr; BPGA</b> ಆಗುವಾಗ <b>NADH</b>',
      '<b>ATP ಉತ್ಪಾದನೆ</b> BPGA &rarr; PGA ಮತ್ತು PEP &rarr; ಪೈರುವಿಕ್ ಆಮ್ಲ ಹಂತಗಳಲ್ಲಿ (ಗ್ಲೂಕೋಸ್‌ಗೆ 4): ಪ್ರತಿ ಗ್ಲೂಕೋಸ್‌ಗೆ <b>ನಿವ್ವಳ 2 ATP + 2 NADH</b>'
    ],
    sections: [
      {h:'ಗ್ಲೈಕಾಲಿಸಿಸ್ ಎಂದರೇನು?', body:'ಗ್ಲೂಕೋಸ್ ಪೈರುವಿಕ್ ಆಮ್ಲವಾಗಿ ವಿಭಜನೆಯಾಗುವುದೇ <b>ಗ್ಲೈಕಾಲಿಸಿಸ್</b>. ಈ ಪದ ಗ್ರೀಕ್‌ನ <b><i>glycos</i></b> (ಸಕ್ಕರೆ) ಮತ್ತು <b><i>lysis</i></b> (ವಿಭಜನೆ) ಪದಗಳಿಂದ ಬಂದಿದೆ. ಈ ಯೋಜನೆಯನ್ನು <b>ಗುಸ್ತಾವ್ ಎಂಬ್ಡೆನ್, ಒಟ್ಟೊ ಮೆಯರ್‌ಹಾಫ್ ಮತ್ತು ಜೆ. ಪರ್ನಾಸ್</b> ನೀಡಿದರು; ಹಾಗಾಗಿ ಇದನ್ನು <b>EMP ಪಥ</b> ಎನ್ನುತ್ತಾರೆ. ಅವಾಯುಜೀವಿಗಳಲ್ಲಿ ಇದೇ <b>ಏಕೈಕ</b> ಉಸಿರಾಟ ಕ್ರಿಯೆ. ಗ್ಲೈಕಾಲಿಸಿಸ್ <b>ಕೋಶದ್ರವ್ಯ</b>ದಲ್ಲಿ ನಡೆಯುತ್ತದೆ ಮತ್ತು <b>ಎಲ್ಲಾ ಜೀವಿಗಳಲ್ಲೂ</b> ಇದೆ. ಗ್ಲೂಕೋಸ್ <b>ಭಾಗಶಃ ಆಕ್ಸಿಡೀಕರಣ</b>ಗೊಂಡು <b>ಎರಡು ಪೈರುವಿಕ್ ಆಮ್ಲದ ಅಣುಗಳು</b> ಉಂಟಾಗುತ್ತವೆ.'},
      {h:'ಗ್ಲೂಕೋಸ್ ಎಲ್ಲಿಂದ ಬರುತ್ತದೆ?', body:'ಸಸ್ಯಗಳಲ್ಲಿ ಗ್ಲೂಕೋಸ್ <b>ಸುಕ್ರೋಸ್</b>ನಿಂದ (ದ್ಯುತಿಸಂಶ್ಲೇಷಣೆಯ ಅಂತಿಮ ಉತ್ಪನ್ನ) ಅಥವಾ <b>ಸಂಗ್ರಹಿತ ಕಾರ್ಬೋಹೈಡ್ರೇಟ್‌</b>ಗಳಿಂದ ಬರುತ್ತದೆ. <b>ಇನ್‌ವರ್ಟೇಸ್</b> ಕಿಣ್ವ ಸುಕ್ರೋಸನ್ನು <b>ಗ್ಲೂಕೋಸ್ ಮತ್ತು ಫ್ರಕ್ಟೋಸ್</b> ಆಗಿ ಪರಿವರ್ತಿಸುತ್ತದೆ; ಎರಡೂ ಗ್ಲೈಕಾಲಿಸಿಸ್ ಪಥವನ್ನು ಸುಲಭವಾಗಿ ಪ್ರವೇಶಿಸುತ್ತವೆ. <b>ಹೆಕ್ಸೋಕೈನೇಸ್</b> ಕಿಣ್ವ ಇವುಗಳನ್ನು <b>ಫಾಸ್ಫೊರಿಲೀಕರಿಸಿ</b> <b>ಗ್ಲೂಕೋಸ್-6-ಫಾಸ್ಫೇಟ್</b> ಮಾಡುತ್ತದೆ. ಇದು <b>ಸಮಾಂಗೀಕರಣ</b>ಗೊಂಡು <b>ಫ್ರಕ್ಟೋಸ್-6-ಫಾಸ್ಫೇಟ್</b> ಆಗುತ್ತದೆ; ನಂತರದ ಹಂತಗಳು ಎರಡಕ್ಕೂ ಒಂದೇ.'},
      {h:'ಶಕ್ತಿ ಹೂಡಿಕೆಯ ಹಂತಗಳು (ATP ಬಳಕೆ)', body:'ಗ್ಲೈಕಾಲಿಸಿಸ್ ಬೇರೆ ಬೇರೆ ಕಿಣ್ವಗಳ ನಿಯಂತ್ರಣದ <b>ಹತ್ತು ಕ್ರಿಯೆಗಳ</b> ಸರಪಳಿ. <b>ATP ಎರಡು ಹಂತಗಳಲ್ಲಿ ಬಳಕೆಯಾಗುತ್ತದೆ</b>: (i) <b>ಗ್ಲೂಕೋಸ್ &rarr; ಗ್ಲೂಕೋಸ್-6-ಫಾಸ್ಫೇಟ್</b> (ಹೆಕ್ಸೋಕೈನೇಸ್) ಮತ್ತು (ii) <b>ಫ್ರಕ್ಟೋಸ್-6-ಫಾಸ್ಫೇಟ್ &rarr; ಫ್ರಕ್ಟೋಸ್ 1,6-ಬೈಸ್ಫಾಸ್ಫೇಟ್</b>. ಫ್ರಕ್ಟೋಸ್ 1,6-ಬೈಸ್ಫಾಸ್ಫೇಟ್ (6C) ಎರಡು ಟ್ರಯೋಸ್ ಫಾಸ್ಫೇಟ್‌ಗಳಾಗಿ <b>ವಿಭಜನೆ</b>ಯಾಗುತ್ತದೆ: <b>ಡೈಹೈಡ್ರಾಕ್ಸಿ ಅಸಿಟೋನ್ ಫಾಸ್ಫೇಟ್ (DHAP)</b> ಮತ್ತು <b>3-ಫಾಸ್ಫೊಗ್ಲಿಸರಾಲ್ಡಿಹೈಡ್ (PGAL)</b>; ಇವು ಪರಸ್ಪರ ಪರಿವರ್ತನೀಯ.'},
      {h:'ಆಕ್ಸಿಡೀಕರಣ ಹಂತ (NADH ಉತ್ಪತ್ತಿ)', body:'NAD<sup>+</sup> ನಿಂದ <b>NADH + H<sup>+</sup></b> ಉಂಟಾಗುವ <b>ಒಂದು ಹಂತ</b>ವಿದೆ: <b>PGAL</b> <b>1,3-ಬೈಸ್ಫಾಸ್ಫೊಗ್ಲಿಸರೇಟ್ (BPGA)</b> ಆಗುವಾಗ. PGAL ನಿಂದ ಎರಡು ರೆಡಾಕ್ಸ್ ಸಮಾನಕಗಳು (ಎರಡು ಹೈಡ್ರೋಜನ್ ಪರಮಾಣುಗಳು) ತೆಗೆದು NAD<sup>+</sup> ಗೆ ವರ್ಗಾಯಿಸಲ್ಪಡುತ್ತವೆ. PGAL ಆಕ್ಸಿಡೀಕರಣಗೊಂಡು <b>ಅಜೈವಿಕ ಫಾಸ್ಫೇಟ್</b> ಜೊತೆ BPGA ಆಗುತ್ತದೆ. ಒಂದು ಗ್ಲೂಕೋಸ್‌ನಿಂದ ಎರಡು PGAL, ಹಾಗಾಗಿ ಪ್ರತಿ ಗ್ಲೂಕೋಸ್‌ಗೆ <b>2 NADH</b>.'},
      {h:'ಶಕ್ತಿ ಲಾಭದ ಹಂತಗಳು (ATP ಉತ್ಪಾದನೆ)', body:'<b>BPGA &rarr; 3-ಫಾಸ್ಫೊಗ್ಲಿಸರಿಕ್ ಆಮ್ಲ (PGA)</b> ಪರಿವರ್ತನೆ ಶಕ್ತಿ ನೀಡುತ್ತದೆ; ಅದು <b>ATP</b> ಆಗಿ ಹಿಡಿಯಲ್ಪಡುತ್ತದೆ. 3-PGA &rarr; 2-ಫಾಸ್ಫೊಗ್ಲಿಸರೇಟ್ &rarr; (H<sub>2</sub>O ಕಳೆದುಕೊಂಡು) <b>ಫಾಸ್ಫೊಈನಾಲ್‌ಪೈರುವೇಟ್ (PEP)</b>. <b>PEP &rarr; ಪೈರುವಿಕ್ ಆಮ್ಲ</b> ಆಗುವಾಗ ಇನ್ನೊಂದು <b>ATP</b>. ಇವು <b>ಆಧಾರವಸ್ತು ಮಟ್ಟದ ಫಾಸ್ಫೊರಿಲೀಕರಣ</b>. ಪ್ರತಿ ಗ್ಲೂಕೋಸ್‌ಗೆ: <b>4 ATP ಉತ್ಪಾದನೆ &minus; 2 ATP ಬಳಕೆ = ನಿವ್ವಳ 2 ATP</b>, ಜೊತೆಗೆ <b>2 NADH + H<sup>+</sup></b>.'},
      {h:'ಪೈರುವಿಕ್ ಆಮ್ಲದ ಗತಿ', body:'<b>ಪೈರುವಿಕ್ ಆಮ್ಲ</b> ಗ್ಲೈಕಾಲಿಸಿಸ್‌ನ ಪ್ರಮುಖ ಉತ್ಪನ್ನ. ಅದರ ಗತಿ ಕೋಶದ ಅಗತ್ಯದ ಮೇಲೆ ಅವಲಂಬಿತ. <b>ಮೂರು ಪ್ರಮುಖ ಮಾರ್ಗಗಳು</b>: <b>ಲ್ಯಾಕ್ಟಿಕ್ ಆಮ್ಲ ಹುದುಗುವಿಕೆ</b>, <b>ಆಲ್ಕೋಹಾಲ್ ಹುದುಗುವಿಕೆ</b> ಮತ್ತು <b>ವಾಯುವಿಕ ಉಸಿರಾಟ</b>. ಹುದುಗುವಿಕೆ ಅನೇಕ ಪ್ರೊಕ್ಯಾರಿಯೋಟ್‌ಗಳು ಮತ್ತು ಏಕಕೋಶೀಯ ಯೂಕ್ಯಾರಿಯೋಟ್‌ಗಳಲ್ಲಿ <b>ಅವಾಯುವಿಕ</b> ಸ್ಥಿತಿಯಲ್ಲಿ ನಡೆಯುತ್ತದೆ. ಗ್ಲೂಕೋಸ್‌ನ <b>ಸಂಪೂರ್ಣ ಆಕ್ಸಿಡೀಕರಣ</b>ಕ್ಕೆ (CO<sub>2</sub> ಮತ್ತು H<sub>2</sub>O) ಜೀವಿಗಳು O<sub>2</sub> ಬೇಕಾದ <b>ಕ್ರೆಬ್ಸ್ ಚಕ್ರ</b> (ವಾಯುವಿಕ ಉಸಿರಾಟ) ಬಳಸುತ್ತವೆ.'}
    ],
